// ponytail: Kaneo has one ticket resource (task) -- no separate issue
// type, so a bugfix ticket is just a task; its label is the closest
// equivalent to Taiga's release-grouping tags. Verify field names against
// the deployed Kaneo version.
const kaneoAuth = { Authorization: `Bearer ${$env.KANEO_TOKEN}` };
const created = await this.helpers.httpRequest({
  method: 'POST',
  url: `${$env.KANEO_URL}/api/task`,
  headers: { ...kaneoAuth, 'Content-Type': 'application/json' },
  body: { projectId: $env.KANEO_PROJECT_ID, title: `[bugfix] Production rollback ${$env.RELEASE_VERSION}`, description: 'Auto-created on /rollback', label: $env.RELEASE_VERSION },
  json: true,
});
return [{ json: { ...$json, incident_ticket_id: created.id } }];
